/**
 * Bounded Asynchronous Task Queue with Backpressure, Cancellation, and Graceful Shutdown
 * 
 * Features:
 * - Bounded queue size with backpressure (waits when full)
 * - Configurable concurrency limit
 * - Task cancellation support
 * - Graceful shutdown (drains existing tasks, rejects new ones)
 * - Typed errors for all failure modes
 * - Deterministic behavior for testing
 */

// ============================================================================
// Types and Interfaces
// ============================================================================

export type Task<T = unknown> = () => Promise<T>;

export interface TaskOptions {
  /** Unique identifier for the task (optional, auto-generated if not provided) */
  id?: string;
  /** Priority of the task (lower number = higher priority, default: 0) */
  priority?: number;
  /** Timeout in milliseconds for the task execution (optional) */
  timeoutMs?: number;
  /** Abort signal for cancellation */
  signal?: AbortSignal;
}

export interface QueueOptions {
  /** Maximum number of tasks that can be queued (backpressure limit) */
  maxQueueSize: number;
  /** Maximum number of tasks that can run concurrently */
  concurrency: number;
  /** Default timeout for tasks in milliseconds (optional) */
  defaultTimeoutMs?: number;
  /** Whether to reject tasks when queue is full (false = wait for space) */
  rejectWhenFull?: boolean;
  /** Maximum number of retries for failed tasks (default: 0) */
  maxRetries?: number;
  /** Delay between retries in milliseconds (default: 100) */
  retryDelayMs?: number;
}

export interface QueueStats {
  /** Number of tasks currently running */
  running: number;
  /** Number of tasks waiting in queue */
  queued: number;
  /** Number of tasks completed successfully */
  completed: number;
  /** Number of tasks that failed */
  failed: number;
  /** Number of tasks that were cancelled */
  cancelled: number;
  /** Total number of tasks submitted */
  totalSubmitted: number;
  /** Whether the queue is currently accepting new tasks */
  accepting: boolean;
}

export interface TaskResult<T = unknown> {
  id: string;
  status: 'completed' | 'failed' | 'cancelled';
  value?: T;
  error?: Error;
  durationMs: number;
  attempts: number;
}

// ============================================================================
// Error Classes
// ============================================================================

export class QueueError extends Error {
  constructor(message: string, public readonly code: string) {
    super(message);
    this.name = 'QueueError';
  }
}

export class QueueFullError extends QueueError {
  constructor(message = 'Queue is full') {
    super(message, 'QUEUE_FULL');
    this.name = 'QueueFullError';
  }
}

export class QueueClosedError extends QueueError {
  constructor(message = 'Queue is closed') {
    super(message, 'QUEUE_CLOSED');
    this.name = 'QueueClosedError';
  }
}

export class TaskTimeoutError extends QueueError {
  constructor(taskId: string, timeoutMs: number) {
    super(`Task ${taskId} timed out after ${timeoutMs}ms`, 'TASK_TIMEOUT');
    this.name = 'TaskTimeoutError';
  }
}

export class TaskCancelledError extends QueueError {
  constructor(taskId: string) {
    super(`Task ${taskId} was cancelled`, 'TASK_CANCELLED');
    this.name = 'TaskCancelledError';
  }
}

export class TaskExecutionError extends QueueError {
  constructor(taskId: string, originalError: Error) {
    super(`Task ${taskId} failed: ${originalError.message}`, 'TASK_EXECUTION_FAILED');
    this.name = 'TaskExecutionError';
    this.cause = originalError;
  }
}

// ============================================================================
// Internal Task Representation
// ============================================================================

interface InternalTask<T = unknown> {
  id: string;
  task: Task<T>;
  options: TaskOptions;
  priority: number;
  createdAt: number;
  resolve: (result: TaskResult<T>) => void;
  reject: (error: Error) => void;
  promise: Promise<TaskResult<T>>;
  status: 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';
  attempts: number;
  abortController: AbortController;
  timeoutId?: ReturnType<typeof setTimeout>;
  startedAt?: number;
}

